@page "/dashboard"
@using sv_41e87f6d94984fc9a4cdfabc9ec8e23c.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-header">
        <strong>@WarehouseState.CurrentWarehouseName</strong> — Inventory Alerts
    </div>
    <div class="card-body">
        <p>
            Low-stock items:
            <span class="badge bg-@(AlertService.LowStockCount > 5 ? "danger" : AlertService.LowStockCount > 0 ? "warning" : "success") fs-5">
                @AlertService.LowStockCount
            </span>
        </p>
        <p class="text-muted mb-0">
            Polling every 10 seconds. Last update: @_lastUpdate.ToString("HH:mm:ss")
        </p>
    </div>
</div>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;
    private DateTime _lastUpdate = DateTime.Now;

    protected override void OnInitialized()
    {
        _alertHandler = () => InvokeAsync(() =>
        {
            _lastUpdate = DateTime.Now;
            StateHasChanged();
        });
        _warehouseHandler = () => InvokeAsync(StateHasChanged);

        AlertService.OnAlertCountChanged += _alertHandler;
        WarehouseState.OnChange += _warehouseHandler;

        // Start polling when dashboard is visible
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        // Stop polling when user leaves the page
        AlertService.StopPolling();

        if (_alertHandler is not null)
            AlertService.OnAlertCountChanged -= _alertHandler;
        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;
    }
}

